cd ~/Documents/Chaipitch_Fullstack_BBL-Test/backend
grep -nE "FOREIGN KEY|UNIQUE INDEX" prisma/migrations/*_init/migration.sql
docker exec -i bbl-bookmarks-postgres psql -U bookmarks -d bookmarks -v ON_ERROR_STOP=0 <<'SQL'
BEGIN;
INSERT INTO "User"(id,"auth0Sub","updatedAt") VALUES ('00000000-0000-4000-8000-00000000000a','a',now()),('00000000-0000-4000-8000-00000000000b','b',now());
INSERT INTO "Collection"(id,name,"ownerId","updatedAt") VALUES ('00000000-0000-4000-8000-0000000000c1','B coll','00000000-0000-4000-8000-00000000000b',now());
\echo '-- 1. A bookmark pointing at B collection (expect FK violation)'
SAVEPOINT s1;
INSERT INTO "Bookmark"(id,url,title,"collectionId","ownerId","updatedAt") VALUES (gen_random_uuid(),'https://x','x','00000000-0000-4000-8000-0000000000c1','00000000-0000-4000-8000-00000000000a',now());
ROLLBACK TO s1;
\echo '-- 2. A uncategorised bookmark (expect OK)'
INSERT INTO "Bookmark"(id,url,title,"ownerId","updatedAt") VALUES (gen_random_uuid(),'https://x','x','00000000-0000-4000-8000-00000000000a',now());
\echo '-- 3. B bookmark in B collection, then delete collection (expect bookmark cascaded)'
INSERT INTO "Bookmark"(id,url,title,"collectionId","ownerId","updatedAt") VALUES (gen_random_uuid(),'https://y','y','00000000-0000-4000-8000-0000000000c1','00000000-0000-4000-8000-00000000000b',now());
DELETE FROM "Collection" WHERE id='00000000-0000-4000-8000-0000000000c1';
SELECT "ownerId", count(*) FROM "Bookmark" GROUP BY 1;
ROLLBACK;
SQL
npx prisma generate 2>&1 | tail -2; ls src/generated/prisma

