  } catch {
    throw new Error('AUTH_JWKS_URI is not a valid URL');
  }

  return {
    issuer: env.AUTH_ISSUER!.trim(),
    audience: env.AUTH_AUDIENCE!.trim(),
    jwksUri,
  };
}

