        where: { auth0Sub: SUB_A },
        data: { profileSyncedAt: new Date(Date.now() - PROFILE_MAX_AGE_MS + 60_000) },
      });
      await me(SUB_A);
      expect(userInfo.calls).toHaveLength(1);
    });
  });

