import { Body, Catch, Controller, Post, type ArgumentsHost, type ExceptionFilter, type INestApplication } from '@nestjs/common';
import { APP_FILTER } from '@nestjs/core';
import { Test } from '@nestjs/testing';
import request from 'supertest';
import { Public } from './auth/public.decorator.js';

const seen: string[] = [];
@Catch()
class ProbeFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    seen.push((exception as Error).constructor.name + ':' + (exception as Error).message.slice(0, 40));
    host.switchToHttp().getResponse().status(418).json({ caughtByFilter: true });
  }
}
@Controller() class C { @Public() @Post('echo') echo(@Body() b: unknown) { return { b }; } }

it('probe: malformed JSON reaches global filter?', async () => {
  const mod = await Test.createTestingModule({ controllers: [C], providers: [{ provide: APP_FILTER, useClass: ProbeFilter }] }).compile();
  const app: INestApplication = mod.createNestApplication(); await app.init();
  const bad = await request(app.getHttpServer()).post('/echo').set('Content-Type', 'application/json').send('{bad json');
  const text = await request(app.getHttpServer()).post('/echo').set('Content-Type', 'text/plain').send('hello');
  const big = await request(app.getHttpServer()).post('/echo').set('Content-Type', 'application/json').send(JSON.stringify({ x: 'a'.repeat(200_000) }));
  console.log('malformed JSON ->', bad.status, JSON.stringify(bad.body));
  console.log('text/plain body ->', text.status, JSON.stringify(text.body));
  console.log('200KB JSON ->', big.status, JSON.stringify(big.body).slice(0, 80));
  console.log('filter saw:', seen);
  await app.close();
});
EOF
