        expect((await c.get(path)).body).toEqual(notFoundBody);
      }
      expect((await b.get(`/shared/collections/${bOwn.id}`)).body).toEqual(notFoundBody);
      expect((await b.get(`/shared/collections/${randomUUID()}`)).body).toEqual(notFoundBody);
