import { useAuth0 } from '@auth0/auth0-react'
import { createContext, useContext, useMemo, type ReactNode } from 'react'
import { config } from '../config'
import { createApiClient, type ApiRequest } from './client'

const ApiContext = createContext<ApiRequest | null>(null)

/** Provides the authenticated API client. Tokens come from Auth0 memory cache (ADR-018d). */
export function ApiProvider({ children }: { children: ReactNode }) {
  const { getAccessTokenSilently, loginWithRedirect } = useAuth0()

  const request = useMemo(
    () =>
      createApiClient({
        baseUrl: config.apiBaseUrl,
        getAccessToken: () => getAccessTokenSilently({ authorizationParams: { audience: config.auth0.audience } }),
        onUnauthorized: () => {
          void loginWithRedirect({ appState: { returnTo: window.location.pathname + window.location.search } })
        },
      }),
    [getAccessTokenSilently, loginWithRedirect],
  )

  return <ApiContext.Provider value={request}>{children}</ApiContext.Provider>
}

export function useApi(): ApiRequest {
  const request = useContext(ApiContext)
  if (!request) throw new Error('useApi must be used inside <ApiProvider>')
  return request
}
