      api<Page<Bookmark>>('GET', '/bookmarks', { query: { cursor: pageParam, collectionId: filters.collectionId, q: filters.q } }),
    initialPageParam: undefined as string | undefined,
    getNextPageParam: (last) => last.nextCursor ?? undefined,
