  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (email: string) => api<Share>('POST', `/collections/${collectionId}/shares`, { body: { email } }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: shareKeys.list(collectionId) }),
  })
}

