      http.get(`${API}/shared/collections/:id`, () => HttpResponse.json(problem(404, 'not_found'), { status: 404 })),
      http.get(`${API}/shared/collections/:id/bookmarks`, () => HttpResponse.json(problem(404, 'not_found'), { status: 404 })),
    )
